package com.crm.customer;
import com.crm.customer.service.*;import com.crm.customer.client.AssignedEmployeeDirectory;import com.crm.customer.repository.*;import com.crm.customer.entity.*;import com.crm.security.AuthenticatedUserPrincipal;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.junit.jupiter.api.*;import java.util.*;import java.time.LocalDateTime;import org.springframework.data.domain.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class AssignedContactPolicyTest {CustomerRepository customers;CustomerInteractionRepository interactions;AssignedEmployeeDirectory directory;AssignedContactService service;Customer row;static void role(String r){var authorities=List.of(new SimpleGrantedAuthority("ROLE_"+r));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"synthetic",authorities),null,authorities));}
 @BeforeEach void setup(){role("EMPLOYEE");customers=mock(CustomerRepository.class);interactions=mock(CustomerInteractionRepository.class);directory=mock(AssignedEmployeeDirectory.class);service=new AssignedContactService(customers,interactions,directory);row=new Customer();row.setId(7L);row.setName("Assigned");row.setAssignedEmployeeId(101L);when(customers.findById(7L)).thenReturn(Optional.of(row));when(customers.lockById(7L)).thenReturn(Optional.of(row));when(directory.own("Bearer synthetic",42L)).thenReturn(101L);when(customers.saveAndFlush(any())).thenAnswer(c->c.getArgument(0));when(interactions.saveAndFlush(any())).thenAnswer(c->{CustomerInteraction r=c.getArgument(0);r.setId(9L);return r;});}@AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void ownerComesFromUidAssociationAndDetailDtoIsReduced(){var r=service.detail("Bearer synthetic",7L);assertEquals("7",r.id());verify(directory).own("Bearer synthetic",42L);assertEquals(Set.of("id","name","email","phone","company","address","contactType"),Arrays.stream(r.getClass().getRecordComponents()).map(java.lang.reflect.RecordComponent::getName).collect(java.util.stream.Collectors.toSet()));}
 @Test void foreignAndArchivedContactsAre404BeforeHistoryRead(){row.setAssignedEmployeeId(102L);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.interactions("Bearer synthetic",7L,0));verifyNoInteractions(interactions);row.setAssignedEmployeeId(101L);row.setArchived(true);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.detail("Bearer synthetic",7L));}
 @Test void listIsFilteredInDatabaseAndPaged(){when(customers.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(Pageable.class))).thenReturn(Page.empty());service.list("Bearer synthetic","Acme",2);verify(customers).findAll(any(org.springframework.data.jpa.domain.Specification.class),argThat((Pageable p)->p.getPageNumber()==2&&p.getPageSize()==20));verify(customers,never()).findAll();}
 @Test void onlyExplicitEmployeeVisibleInteractionsAreRead(){when(interactions.findByCustomerIdAndEmployeeIdAndEmployeeVisibleTrue(eq(7L),eq(101L),any())).thenReturn(Page.empty());service.interactions("Bearer synthetic",7L,0);verify(interactions).findByCustomerIdAndEmployeeIdAndEmployeeVisibleTrue(eq(7L),eq(101L),any());verify(interactions,never()).findByCustomerIdOrderByOccurredAtDesc(any());}
 @Test void newInteractionInheritsEmployeeAndIsExplicitlyVisible(){service.add("Bearer synthetic",7L,new AssignedContactService.Interaction("CALL",LocalDateTime.of(2026,11,5,12,0)," Call "));verify(interactions).saveAndFlush(argThat(r->r.getEmployeeId().equals(101L)&&r.getCustomerId().equals(7L)&&r.isEmployeeVisible()&&r.getNotes().equals("Call")));}
 @Test void editingCannotChangeAssignmentNameTypeOrInternalClassification(){service.edit("Bearer synthetic",7L,new AssignedContactService.Edit("a@example.invalid",null,"New address"));assertEquals(101L,row.getAssignedEmployeeId());assertEquals("Assigned",row.getName());assertEquals("CUSTOMER",row.getContactType());assertEquals("New address",row.getAddress());}
 @Test void invalidEditOrInteractionDoesNotMutate(){assertThrows(IllegalArgumentException.class,()->service.edit("Bearer synthetic",7L,new AssignedContactService.Edit("bad",null,null)));assertThrows(IllegalArgumentException.class,()->service.add("Bearer synthetic",7L,new AssignedContactService.Interaction("SMS",LocalDateTime.now(),"Text")));verify(customers,never()).saveAndFlush(any());verify(interactions,never()).saveAndFlush(any());}
 @Test void revokedOrUnavailableAssociationFailsClosed(){when(directory.own(any(),anyLong())).thenThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.detail("Bearer synthetic",7L));verifyNoInteractions(customers);}
 @Test void administrativeAndClientRolesCannotUseEmployeePersonalService(){for(String r:List.of("CLIENT","ADMIN","SUPER_ADMIN")){role(r);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.detail("Bearer synthetic",7L));}verifyNoInteractions(customers,directory);}
}
